import{_ as t,a as i}from"./chunks/isaac-sim-rbq-test.DJ9nZooS.js";import{_ as a,o as e,c as d,a5 as o}from"./chunks/framework.Cct9zD0Q.js";const m=JSON.parse('{"title":"Isaac Sim","description":"","frontmatter":{"layout":"doc","outline":"deep"},"headers":[],"relativePath":"ko/software/simulator/isaac-sim.md","filePath":"ko/software/simulator/isaac-sim.md","lastUpdated":1795599730000}'),r={name:"ko/software/simulator/isaac-sim.md"};function l(h,s,n,c,p,k){return e(),d("div",null,[...s[0]||(s[0]=[o('<h1 id="isaac-sim" tabindex="-1">Isaac Sim <a class="header-anchor" href="#isaac-sim" aria-label="Permalink to &quot;Isaac Sim&quot;">​</a></h1><h2 id="소개" tabindex="-1">소개 <a class="header-anchor" href="#소개" aria-label="Permalink to &quot;소개&quot;">​</a></h2><p><strong>RBQ 4족 보행 로봇을 위한 Isaac Sim 시뮬레이터.</strong></p><p>Isaac Sim은 <strong>RBQ 소프트웨어 스택 전체</strong>를 실행하여, <strong>SLAM 연구, 자율주행 테스트, 실기에서 하던 모든 테스트</strong>를 시뮬레이션에서 할 수 있게 합니다. 같은 토픽으로 실행 중인 RBQ 스택에 DDS 피어로 참여하므로 로봇 소프트웨어를 고치지 않고 그대로 씁니다. 로봇 모델은 <a href="/RBQ/nightly/ko/software/simulator/rbq-lab.html">Isaac Lab</a> 학습 환경과 같고, 계단·경사로·험지가 있는 USD 월드를 함께 제공합니다.</p><table tabindex="0"><thead><tr><th style="text-align:center;">Isaac Sim</th></tr></thead><tbody><tr><td style="text-align:center;"><img src="'+t+`" alt="Isaac Sim" width="600"></td></tr></tbody></table><h2 id="구성" tabindex="-1">구성 <a class="header-anchor" href="#구성" aria-label="Permalink to &quot;구성&quot;">​</a></h2><table tabindex="0"><thead><tr><th>경로</th><th>설명</th></tr></thead><tbody><tr><td><code>rbq_simulator/rbq_sim/rbq_sim/</code></td><td>시뮬레이터 소스 (Python)</td></tr><tr><td><code>rbq_simulator/rbq_sim/worlds/</code></td><td>패키지에 포함된 USD 월드</td></tr><tr><td><code>rbq_simulator/rbq_sim/scripts/</code></td><td>실행 / 환경 스크립트</td></tr><tr><td><code>scripts/issac_sim.bash</code></td><td>Motion, Isaac Sim, 웹 UI를 한꺼번에 띄웁니다</td></tr><tr><td><code>scripts/install/isaacsim.bash</code></td><td>Isaac Sim을 설치합니다</td></tr></tbody></table><h2 id="run" tabindex="-1">RBQ 스택과 함께 실행 <a class="header-anchor" href="#run" aria-label="Permalink to &quot;RBQ 스택과 함께 실행 {#run}&quot;">​</a></h2><p class="sub-title">설치</p><ul><li>Ubuntu 22.04와 NVIDIA RTX GPU. NVIDIA 공식 목록은 <a href="https://docs.isaacsim.omniverse.nvidia.com/5.1.0/installation/requirements.html" target="_blank" rel="noreferrer">Isaac Sim 5.1 요구 사항</a>에 있습니다.</li><li>Isaac Sim 5.1.0과 Isaac Lab. 아래 설치 스크립트가 Isaac Lab과 같은 conda 환경(<code>rbq-lab</code>)에 설치하며, 디스크를 약 22 GB 씁니다.</li></ul><table tabindex="0"><thead><tr><th></th><th>테스트한 PC</th><th>권장</th></tr></thead><tbody><tr><td>CPU</td><td>Intel Core Ultra 7 265KF (20코어)</td><td>최근 세대 8코어 이상. 물리는 CPU 코어 하나에서 돌아서 단일 코어 성능이 실시간 배율을 정합니다</td></tr><tr><td>GPU</td><td>GeForce RTX 5080, 16 GB</td><td>GeForce RTX 5080 이상, 16 GB</td></tr><tr><td>RAM</td><td>64 GB</td><td>32 GB 이상</td></tr><tr><td>디스크</td><td>NVMe SSD</td><td>SSD 여유 50 GB</td></tr><tr><td>드라이버</td><td>NVIDIA 580.159</td><td>NVIDIA 580 계열</td></tr></tbody></table><p>테스트한 PC에서 RBQ 스택과 함께 돌렸을 때 창 없이 실시간의 약 0.85배, 창을 띄우면 약 0.6배였고, RAM 약 6 GB와 GPU 메모리 약 1.5 GB를 썼습니다.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Clone</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clone</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://github.com/RainbowRobotics/RBQ.git</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> RBQ</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Isaac Sim 설치 (최초 1회, 일반 사용자로 실행. apt 단계에서만 sudo를 묻습니다)</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bash</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/install/isaacsim.bash</span></span></code></pre></div><hr class="sub-divider"><p class="sub-title">Local</p><p><strong>한꺼번에</strong> — Motion, Isaac Sim, 웹 UI를 터미널 탭으로 나눠 띄웁니다:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bash</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/issac_sim.bash</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bash</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/issac_sim.bash</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --world</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> stairs_course</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bash</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/issac_sim.bash</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --headless</span></span></code></pre></div><p><strong><code>--core</code> 로</strong> — 시뮬레이터가 RBQ 코어 SW도 함께 띄웁니다. 코어 SW는 자기 터미널 탭에서 돌고 시뮬레이터가 끝나도 계속 돕니다. 멈추려면 그 탭들을 닫습니다:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bash</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> rbq_simulator/rbq_sim/scripts/run.bash</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --core</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --world</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> stairs_course</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bash</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> rbq_simulator/rbq_sim/scripts/run.bash</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --core</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --vision</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --headless</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bash</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> rbq_simulator/rbq_sim/scripts/run.bash</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --core</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --rviz</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --world</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> stairs_course</span></span></code></pre></div><p><strong>따로</strong> — RBQ 스택과 시뮬레이터를 터미널 두 개에서 띄웁니다:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bash</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/start_motion.bash</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --sim</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">                                   # 터미널 1, sudo를 묻습니다</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bash</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> rbq_simulator/rbq_sim/scripts/run.bash</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --world</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> stairs_course</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">      # 터미널 2</span></span></code></pre></div><p>브라우저에서 <code>http://127.0.0.1:8080</code> 을 열어 로봇을 조종합니다(<code>rb</code> / <code>rainbow2026</code> 으로 로그인). 처음 실행할 때는 Isaac Sim이 셰이더 캐시를 만드느라 몇 분 걸립니다.</p><hr class="sub-divider"><p class="sub-title">Docker</p><p>Isaac Sim 용 Docker 이미지는 아직 없습니다. 위와 같이 호스트에 설치해서 씁니다.</p><hr class="sub-divider"><p class="sub-title">제어 주기</p><p>Isaac Sim은 실시간보다 느리게 돕니다. 창 없이 약 0.85배, 창을 띄우면 약 0.6배입니다. 시뮬레이터가 Motion을 시뮬레이션 시간에 맞춰 돌리므로 로봇 소프트웨어는 여전히 2 ms 제어 주기를 봅니다:</p><ul><li>물리는 1 kHz로 돕니다. 시뮬레이션 시간 2 ms마다 상태를 보내고, Motion의 응답을 받은 뒤에 다음으로 넘어갑니다.</li><li>그래서 렌더링이 아무리 느려도 Motion은 시뮬레이션 시간 2 ms마다 정확히 한 번 제어를 돕니다. 화면에서 느리게 보일 뿐 동작은 같습니다.</li><li>콘솔에 5초마다 <code>lockstep ON acked 1472/1472 timeouts 0</code> 같은 줄이 찍힙니다. <code>timeouts 0</code> 이면 건너뛴 제어 주기가 없다는 뜻입니다.</li><li>Motion이 없으면 시뮬레이터는 앉은 자세를 유지하고 실시간 속도로 돕니다.</li></ul><div class="sb sb-note"><div class="sb-icon"><span class="sb-note-i" aria-hidden="true">i</span></div><div class="sb-content"><p class="custom-block-title">NOTE — DDS 네트워킹</p><p>시뮬레이터는 RBQ 스택과 루프백 인터페이스(<code>lo</code>)에서 <strong>DDS 도메인 0</strong>을 공유합니다. 대부분의 PC는 <code>lo</code> 에 멀티캐스트가 없어서 <code>run.bash</code> 가 <code>rbq_simulator/rbq_sim/cyclonedds_sim.xml</code> 을 씁니다. 시뮬레이터는 한 번에 하나만 띄웁니다. MuJoCo, Gazebo, Isaac Sim은 같은 토픽을 씁니다.</p></div></div><h2 id="옵션" tabindex="-1">옵션 <a class="header-anchor" href="#옵션" aria-label="Permalink to &quot;옵션&quot;">​</a></h2><table tabindex="0"><thead><tr><th>옵션</th><th>의미</th></tr></thead><tbody><tr><td><code>--world &lt;name&gt;</code></td><td>불러올 월드. 기본 <code>rbq_test</code>. <a href="#worlds">월드</a> 참조</td></tr><tr><td><code>--headless</code></td><td>Isaac Sim 창 없이 실행합니다</td></tr><tr><td><code>-i</code>, <code>--interface &lt;name&gt;</code></td><td>DDS 네트워크 인터페이스. 기본 <code>lo</code></td></tr><tr><td><code>--vision</code></td><td>로봇 카메라를 시뮬레이션합니다. <a href="#cameras">카메라</a> 참조</td></tr><tr><td><code>--livox</code> / <code>--ouster</code></td><td>LiDAR를 시뮬레이션합니다. 둘 중 하나만 씁니다. <a href="#lidar">LiDAR</a> 참조</td></tr><tr><td><code>--rviz</code></td><td>RViz 도 띄웁니다. <a href="#ros2">ROS 2</a> 참조</td></tr><tr><td><code>--core</code></td><td><code>run.bash</code> 전용. RBQ 코어 SW도 함께 띄우고 웹 UI를 엽니다. <code>--vision</code> 이면 Vision 스택도 띄우고, <code>--no-gui</code> 면 브라우저를 열지 않습니다</td></tr></tbody></table><p><code>scripts/issac_sim.bash</code> 도 <code>--world</code>, <code>--headless</code>, <code>--vision</code>, <code>--rviz</code>, <code>-i</code> 를 받습니다. 여기서 <code>--vision</code> 은 카메라와 함께 Vision 스택도 띄웁니다.</p><p>사족만 있습니다. Isaac Sim 에는 휠타입 RBQ(<code>--wheel</code>)가 없습니다.</p><hr class="sub-divider"><p class="sub-title" id="worlds">월드</p><table tabindex="0"><thead><tr><th>종류</th><th><code>--world</code></th><th>비고</th></tr></thead><tbody><tr><td>RBQ test world</td><td><code>rbq_test</code> (기본)</td><td>MuJoCo · Gazebo와 같은 RBQ test world. 오프라인에서도 동작합니다</td></tr><tr><td>평지</td><td><code>empty</code></td><td>내려받을 것 없음</td></tr><tr><td>Isaac Sim 기본 제공</td><td><code>grid</code>, <code>office</code>, <code>hospital</code>, <code>simple_room</code>, <code>warehouse</code>, <code>depot</code>, <code>warehouse_shelves</code>, <code>warehouse_forklifts</code></td><td>처음 쓸 때 NVIDIA에서 내려받습니다</td></tr><tr><td>패키지 포함</td><td><code>stairs_course</code>, <code>two_floor_office</code>, <code>terrain_park</code></td><td>오프라인에서도 동작합니다</td></tr></tbody></table><table tabindex="0"><thead><tr><th>패키지 포함 월드</th><th>내용</th></tr></thead><tbody><tr><td><code>rbq_test</code></td><td>MuJoCo와 같은 배치. 피라미드 계단(0.15 m x 6단), 20° / 30° 경사로, 장애물 바(0.10 / 0.15 / 0.20 m), 미끄러운 바닥, ArUco 마커가 붙은 도킹 스테이션, 그레이팅 계단, 공과 벽돌</td></tr><tr><td><code>stairs_course</code></td><td>32 x 16 m 홀. 계단(0.10 m, 0.15 m 높이), 10° / 15° / 20° 경사로, 울퉁불퉁한 블록, 징검돌, 연석</td></tr><tr><td><code>two_floor_office</code></td><td>꺾인 계단(0.15 m x 20단)으로 이어진 2층 건물. 층마다 방을 도는 동선이 있습니다</td></tr><tr><td><code>terrain_park</code></td><td>40 x 40 m 야외 공원. 피라미드 계단, 거친 지형, 15° 언덕, 계단과 경사로가 붙은 광장</td></tr></tbody></table><table tabindex="0"><thead><tr><th style="text-align:center;">RBQ test world (기본)</th></tr></thead><tbody><tr><td style="text-align:center;"><img src="`+i+`" alt="RBQ test world" width="600"></td></tr></tbody></table><p class="sub-title">내 USD 쓰기</p><p><code>rbq_simulator/rbq_sim/rbq_sim/worlds.py</code> 의 <code>WORLDS</code> 에 항목을 추가하고 이름으로 실행합니다:</p><div class="language-python vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">python</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;my_site&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;spawn&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: (</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0.0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0.0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0.30</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0.0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">),   </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># x, y, z [m], yaw [rad]</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">            &quot;usd&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;/path/to/my_site.usd&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">},    </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 절대경로, 또는 file:// / omniverse:// 주소</span></span></code></pre></div><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bash</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/issac_sim.bash</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --world</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> my_site</span></span></code></pre></div><p>USD가 평지 바닥을 대신하므로 USD 안에 충돌 판정이 있는 바닥이 있어야 합니다. 로봇은 시작 위치에서 앉은 자세로 시작합니다. 바닥 높이가 0이 아니면 그만큼 <code>z</code> 를 올립니다.</p><h2 id="sensors" tabindex="-1">센서 <a class="header-anchor" href="#sensors" aria-label="Permalink to &quot;센서 {#sensors}&quot;">​</a></h2><p class="sub-title" id="cameras">카메라</p><p><code>--vision</code> 을 붙이면 로봇 카메라 6대를 MuJoCo와 같은 위치에 달고 같은 토픽으로 발행합니다. 그래서 Vision 스택(HAL)이 MuJoCo에서와 똑같이 읽습니다:</p><table tabindex="0"><thead><tr><th>센서</th><th>카메라</th><th>스트림</th></tr></thead><tbody><tr><td><code>sensor_0</code>–<code>sensor_3</code></td><td>하부 (앞, 중앙 앞, 중앙 뒤, 뒤)</td><td>depth, IR</td></tr><tr><td><code>sensor_4</code></td><td>전방</td><td>depth, RGB</td></tr><tr><td><code>sensor_5</code></td><td>후방</td><td>depth, RGB</td></tr></tbody></table><p>카메라마다 640 x 360, 시뮬레이션 시간 기준 15 fps입니다. 토픽은 <code>rt/rbq/vision/sensor_N/&lt;stream&gt;/compressed</code>(RGB와 IR은 JPEG, depth는 mm 단위 16비트 PNG)이고, 옆에 <code>camera_info</code> 와 <code>tf</code> 가 있습니다. 카메라 6대 렌더링은 무겁습니다. 테스트한 PC에서 창 없이 돌릴 때 실시간 배율이 약 0.85배에서 약 0.36배로 떨어져, 실제 시간으로는 초당 약 5프레임이 나옵니다.</p><hr class="sub-divider"><p class="sub-title" id="lidar">LiDAR</p><p><code>--livox</code> 와 <code>--ouster</code> 는 <a href="/RBQ/nightly/ko/software/simulator/mujoco.html">MuJoCo</a>, <a href="/RBQ/nightly/ko/software/simulator/gazebo.html">Gazebo</a>와 같은 LiDAR를 같은 토픽으로 발행하므로, Vision 스택(HAL)과 SLAM이 그대로 읽습니다. RBQ 코어 SW에도 같은 옵션을 줍니다(<code>--core</code> 는 <code>-p livox</code> / <code>-p ouster</code> 로 넘깁니다).</p><table tabindex="0"><thead><tr><th>옵션</th><th>LiDAR</th><th>스캔</th></tr></thead><tbody><tr><td><code>--livox</code></td><td>Livox Mid-360 두 대, <code>lidar_front</code> / <code>lidar_rear</code></td><td>MuJoCo와 같은 Mid-360 비반복 패턴, 프레임당 24000점, 50 m</td></tr><tr><td><code>--ouster</code></td><td>뒤 데크의 Ouster OS1, <code>lidar_ouster</code></td><td>1024 x 32, ±22.5°, 0.1–100 m</td></tr></tbody></table><p>LiDAR마다 시뮬레이션 시간 기준 10 Hz로 스캔하고 <code>rt/rbq/lidar/&lt;name&gt;</code>(센서 프레임 PointCloud2), <code>&lt;name&gt;/imu</code>(200 Hz), <code>&lt;name&gt;/tf</code> 를 발행합니다. 레이는 시작 시점의 월드에 쏘므로 로봇 자신과 나중에 움직인 물체는 보이지 않습니다.</p><hr class="sub-divider"><p class="sub-title" id="imu">IMU</p><p>몸체 IMU 는 매 제어 주기 로봇 상태와 함께 Motion 으로 가고, RBQ 스택이 <code>rt/rbq/imu</code> 로 발행합니다. <code>--livox</code> 나 <code>--ouster</code> 이면 LiDAR 마다 자기 IMU(<code>rt/rbq/lidar/&lt;name&gt;/imu</code>, 200 Hz)도 있습니다.</p><h2 id="ros2" tabindex="-1">ROS 2 <a class="header-anchor" href="#ros2" aria-label="Permalink to &quot;ROS 2 {#ros2}&quot;">​</a></h2><p>시뮬레이터와 RBQ 스택이 루프백(<code>lo</code>)에서 <strong>ROS 2 도메인 0</strong>으로 발행하므로, ROS 2 노드에서 보통 토픽으로 보입니다. 브리지는 필요 없습니다. 노드를 다음 환경 변수와 함께 실행하세요 (CycloneDDS를 사용해야 합니다. 대부분의 PC는 <code>lo</code> 에 멀티캐스트가 없어서 <code>run.bash</code> 와 같은 XML 을 씁니다):</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> RMW_IMPLEMENTATION</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">rmw_cyclonedds_cpp</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> ROS_DOMAIN_ID</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> CYCLONEDDS_URI</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">file://$(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">pwd</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)/rbq_simulator/rbq_sim/cyclonedds_sim.xml   </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 저장소 루트에서</span></span></code></pre></div><p>모든 토픽은 Reliable 입니다. History 는 RBQ 스택 토픽(<code>/rbq/imu</code>, <code>/rbq/joint_states</code>, <code>/rbq/odometry</code>, <code>/tf</code> 의 <code>local_world → base_link</code>)이 KeepLast 8, 시뮬레이터 토픽이 KeepLast 1 입니다.</p><div class="ros-topics"><table tabindex="0"><thead><tr><th>ROS 2 토픽</th><th>타입</th><th>비고</th></tr></thead><tbody><tr><td><code>/clock</code></td><td><code>rosgraph_msgs/msg/Clock</code></td><td>시뮬 시각</td></tr><tr><td><code>/rbq/imu</code></td><td><code>sensor_msgs/msg/Imu</code></td><td>몸체 IMU</td></tr><tr><td><code>/rbq/joint_states</code></td><td><code>sensor_msgs/msg/JointState</code></td><td>관절 상태</td></tr><tr><td><code>/rbq/odometry</code></td><td><code>nav_msgs/msg/Odometry</code></td><td>상태추정</td></tr><tr><td><code>/tf</code></td><td><code>tf2_msgs/msg/TFMessage</code></td><td>좌표 변환</td></tr><tr><td><code>/rbq/lidar/&lt;name&gt;</code></td><td><code>sensor_msgs/msg/PointCloud2</code></td><td>LiDAR 점군</td></tr><tr><td><code>/rbq/lidar/&lt;name&gt;/imu</code></td><td><code>sensor_msgs/msg/Imu</code></td><td>LiDAR IMU</td></tr><tr><td><code>/rbq/vision/sensor_N/&lt;stream&gt;/compressed</code></td><td><code>sensor_msgs/msg/CompressedImage</code></td><td>카메라 영상</td></tr></tbody></table></div><p><code>/tf</code> 에 Ground Truth 체인은 없습니다. <code>local_world → base_link</code> 는 RBQ SW 가 발행하는 <strong>상태추정</strong> 값(IMU + 레그 오도메트리, 부팅/리셋 시점이 원점)입니다. Isaac Sim 은 실시간보다 느리게 돌아서, RBQ 스택이 시뮬레이터의 <code>/clock</code> 시각으로 토픽을 찍습니다. 노드는 <code>use_sim_time:=true</code> 로 실행합니다. 500 Hz 토픽은 구독하는 노드가 있을 때만 발행됩니다.</p><p><code>--rviz</code> 는 <a href="/RBQ/nightly/ko/software/simulator/gazebo.html#ros2">Gazebo</a> 패키지의 기본 센서 뷰(로봇 모델, TF, 카메라, LiDAR)로 RViz 를 엽니다. 그 패키지를 한 번 빌드합니다. ROS 2 Humble 은 필요하지만 Gazebo 는 필요 없습니다:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">source</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /opt/ros/humble/setup.bash</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> &amp;&amp; (</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> rbq_simulator/rbq_gazebo/ros2</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> &amp;&amp; </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">colcon</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --symlink-install</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bash</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> rbq_simulator/rbq_sim/scripts/run.bash</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --core</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --rviz</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bash</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> rbq_simulator/rbq_sim/scripts/run.bash</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --core</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --rviz</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --livox</span></span></code></pre></div><p>관절 상태와 Fixed Frame <code>local_world</code> 는 RBQ 스택이 보내므로 <code>--core</code> 와 함께 쓰거나 코어 SW를 먼저 띄웁니다.</p><h2 id="관련-문서" tabindex="-1">관련 문서 <a class="header-anchor" href="#관련-문서" aria-label="Permalink to &quot;관련 문서&quot;">​</a></h2><ul><li><a href="/RBQ/nightly/ko/software/simulator/mujoco.html">MuJoCo</a> — MuJoCo 시뮬레이터</li><li><a href="/RBQ/nightly/ko/software/simulator/gazebo.html">Gazebo</a> — Ignition Gazebo 시뮬레이터</li><li><a href="/RBQ/nightly/ko/software/simulator/rbq-gym.html">Isaac Gym</a> / <a href="/RBQ/nightly/ko/software/simulator/rbq-lab.html">Isaac Lab</a> — 강화학습 학습 환경</li><li><a href="/RBQ/nightly/ko/software/simulator/overview.html">시뮬레이터 개요</a></li></ul>`,68)])])}const u=a(r,[["render",l]]);export{m as __pageData,u as default};
